<script setup lang="ts">
import { ref, onMounted, onUnmounted, computed, watch } from 'vue';
import { storageService } from '@/00-storage/service';
import type { BinaryObject } from '@/01-models/types';
import {
  SearchIcon, ArrowUpIcon, ArrowDownIcon, DownloadIcon,
  EyeIcon, HardDriveIcon,
  Trash2Icon, RefreshCwIcon, LayoutGridIcon, ListIcon, FileIcon,
} from 'lucide-vue-next';
import { Semaphore } from '@/utils/concurrency';
import { defineAsyncComponentAndLoadOnMounted } from '@/utils/vue';
// Lazily load the preview modal since it's only shown after user interaction, but prefetch it when idle.
const BinaryObjectPreviewModal = defineAsyncComponentAndLoadOnMounted({ loader: () => import('./BinaryObjectPreviewModal.vue') });
import { useImagePreview } from '@/composables/useImagePreview';
import { useBinaryActions } from '@/composables/useBinaryActions';
import { idToRaw, toBinaryObjectId } from '@/01-models/ids';
import type { BinaryObjectId } from '@/01-models/ids';
import { lazyStrings } from '@/strings';

const objects = ref<BinaryObject[]>([]);
const isLoading = ref(true);
const searchQuery = ref('');
const sortBy = ref<'createdAt' | 'name' | 'size' | 'mimeType'>('createdAt');
const sortOrder = ref<'asc' | 'desc'>('desc');
const viewMode = ref<'table' | 'grid'>('table');

const { state: previewState, openPreview, closePreview } = useImagePreview();
const { deleteBinaryObject, downloadBinaryObject } = useBinaryActions();

// Incremental rendering
const displayLimit = ref(60); // Start with a bit more
const loadMoreSentinel = ref<HTMLElement | null>(null);
const isAddingItems = ref(false);

// Limit concurrent image processing to keep UI responsive
const thumbnailSemaphore = new Semaphore({ maxConcurrency: 2 }); // Reduced slightly for better scroll priority

const fetchObjects = async () => {
  isLoading.value = true;
  const newObjects: BinaryObject[] = [];
  try {
    const iterable = storageService.listBinaryObjects();
    for await (const obj of iterable) {
      newObjects.push(obj);
    }
    objects.value = newObjects;
    displayLimit.value = 60;
  } catch (error) {
    console.error('Failed to fetch binary objects:', error);
  } finally {
    isLoading.value = false;
  }
};

const loadMore = () => {
  if (isAddingItems.value) return;
  if (displayLimit.value < filteredObjects.value.length) {
    isAddingItems.value = true;
    displayLimit.value += 60; // Larger increments = fewer layout passes
    setTimeout(() => {
      isAddingItems.value = false;
    }, 200);
  }
};

const filteredObjects = computed(() => {
  let result = [...objects.value];

  if (searchQuery.value) {
    const q = searchQuery.value.toLowerCase();
    result = result.filter((f) => {
      const displayName = f.name || lazyStrings.binaryObjects__unnamed();
      return (
        displayName?.toLowerCase().includes(q) === true ||
        idToRaw({ id: f.id }).toLowerCase().includes(q) ||
        f.mimeType.toLowerCase().includes(q)
      );
    });
  }

  const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });

  result.sort((a, b) => {
    let cmp = 0;
    switch (sortBy.value) {
    case 'createdAt':
      cmp = a.createdAt - b.createdAt;
      break;
    case 'size':
      cmp = a.size - b.size;
      break;
    case 'mimeType':
      cmp = collator.compare(a.mimeType, b.mimeType);
      break;
    case 'name':
    default:
      cmp = collator.compare(a.name || '', b.name || '');
      break;
    }
    const cmpResult = (() => {
      switch (sortOrder.value) {
      case 'asc': return cmp;
      case 'desc': return -cmp;
      default: {
        const _ex: never = sortOrder.value;
        console.error('Unhandled sort order:', _ex);
        return cmp;
      }
      }
    })();
    return cmpResult;
  });

  return result;
});

const renderedObjects = computed(() => {
  return filteredObjects.value.slice(0, displayLimit.value);
});

// Fast O(1) lookup
const objectMap = computed(() => {
  const map = new Map<BinaryObjectId, BinaryObject>();
  for (const obj of objects.value) {
    map.set(obj.id, obj);
  }
  return map;
});

// Reset display limit when filtering or sorting changes
watch([searchQuery, sortBy, sortOrder], () => {
  displayLimit.value = 60;
});

const handleSort = ({ key }: { key: typeof sortBy.value }) => {
  if (sortBy.value === key) {
    sortOrder.value = (() => {
      switch (sortOrder.value) {
      case 'asc': return 'desc';
      case 'desc': return 'asc';
      default: {
        const _ex: never = sortOrder.value;
        return _ex;
      }
      }
    })();
  } else {
    sortBy.value = key;
    sortOrder.value = (() => {
      switch (key) {
      case 'createdAt':
      case 'size':
        return 'desc';
      case 'name':
      case 'mimeType':
        return 'asc';
      default: {
        const _ex: never = key;
        return _ex;
      }
      }
    })();
  }
};

const formatSize = ({ bytes }: { bytes: number }) => {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
};

const formatDate = ({ timestamp }: { timestamp: number }) => {
  return new Date(timestamp).toLocaleString();
};

const handleDownload = async ({ obj }: { obj: BinaryObject }) => {
  await downloadBinaryObject({ obj, memoryBlob: undefined });
};

const handlePreview = ({ obj }: { obj: BinaryObject }) => {
  openPreview({ objects: filteredObjects.value.map(object => ({ ...object, memoryBlob: undefined })), initialId: obj.id });
};

const handleDelete = async ({ obj }: { obj: BinaryObject }) => {
  const success = await deleteBinaryObject({ id: obj.id });
  if (success) {
    objects.value = objects.value.filter(o => o.id !== obj.id);
  }
};

// Thumbnail Management
const thumbnails = ref(new Map<BinaryObjectId, string>()); // Values are Object URLs
const thumbnailLoading = ref(new Set<BinaryObjectId>());
const visibleIds = new Set<string>(); // Not reactive for performance
const thumbnailCount = ref(0);

const createThumbnailUrl = ({ blob, size = 120 }: { blob: Blob, size?: number }): Promise<string> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(blob);
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        URL.revokeObjectURL(url);
        reject(new Error('Canvas context not available'));
        return;
      }

      let width = img.width;
      let height = img.height;
      if (width > height) {
        if (width > size) {
          height *= size / width;
          width = size;
        }
      } else {
        if (height > size) {
          width *= size / height;
          height = size;
        }
      }

      canvas.width = width;
      canvas.height = height;
      ctx.drawImage(img, 0, 0, width, height);

      URL.revokeObjectURL(url);

      // Use toBlob + createObjectURL: significantly faster and more memory efficient than toDataURL
      canvas.toBlob((thumbnailBlob) => {
        if (thumbnailBlob) {
          resolve(URL.createObjectURL(thumbnailBlob));
        } else {
          reject(new Error('Canvas toBlob failed'));
        }
      }, 'image/jpeg', 0.7);
    };
    img.onerror = (e) => {
      URL.revokeObjectURL(url);
      reject(e);
    };
    img.src = url;
  });
};

const loadThumbnail = async ({ obj }: { obj: BinaryObject }) => {
  if (thumbnails.value.has(obj.id) || thumbnailLoading.value.has(obj.id)) return;
  if (!obj.mimeType.startsWith('image/')) return;

  thumbnailLoading.value.add(obj.id);
  try {
    await thumbnailSemaphore.run({
      task: async () => {
        const blob = await storageService.getFile({ binaryObjectId: obj.id });
        if (blob) {
        // requestIdleCallback (with fallback) to avoid blocking the main thread during scroll
          const scheduleWork: typeof window.requestIdleCallback = window.requestIdleCallback || ((cb) => setTimeout(cb, 1));

          const thumbUrl = await new Promise<string>((resolve, reject) => {
            scheduleWork(async () => {
              try {
                resolve(await createThumbnailUrl({ blob }));
              } catch (e) {
                reject(e);
              }
            });
          });

          if (!thumbnails.value.has(obj.id)) {
            thumbnails.value.set(obj.id, thumbUrl);
            thumbnailCount.value++;
          }
        }
      },
    });
  } catch (e) {
    console.error('Failed to load thumbnail:', e);
  } finally {
    thumbnailLoading.value.delete(obj.id);
  }
};

// Debounced memory cleanup
let cleanupTimeout: number | null = null;

const performThumbnailCleanup = () => {
  if (thumbnailCount.value <= 300) return;

  const idsToDelete: BinaryObjectId[] = [];
  for (const id of thumbnails.value.keys()) {
    if (!visibleIds.has(idToRaw({ id }))) {
      idsToDelete.push(id);
    }
    if (thumbnailCount.value - idsToDelete.length <= 200) break;
  }

  for (const id of idsToDelete) {
    const url = thumbnails.value.get(id);
    if (url) URL.revokeObjectURL(url); // Clean up browser memory
    thumbnails.value.delete(id);
    thumbnailCount.value--;
  }
};

// Intersection Observers
let itemObserver: IntersectionObserver | null = null;
let sentinelObserver: IntersectionObserver | null = null;
const observedElements = new WeakSet<HTMLElement>();

onMounted(() => {
  fetchObjects();

  // 1. Sentinel
  sentinelObserver = new IntersectionObserver((entries) => {
    const entry = entries[0];
    if (entry?.isIntersecting && !isLoading.value) {
      loadMore();
    }
  }, { threshold: 0, rootMargin: '800px' });

  watch(loadMoreSentinel, (el) => {
    if (el) sentinelObserver?.observe(el);
  }, { immediate: true });

  // 2. Individual items
  itemObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      const target = entry.target as HTMLElement;
      const id = target.dataset.id;
      if (!id) return;

      if (entry.isIntersecting) {
        visibleIds.add(id);
        const obj = objectMap.value.get(toBinaryObjectId({ raw: id }));
        if (obj) loadThumbnail({ obj });
      } else {
        visibleIds.delete(id);
        if (thumbnailCount.value > 300) {
          if (cleanupTimeout) clearTimeout(cleanupTimeout);
          cleanupTimeout = window.setTimeout(performThumbnailCleanup, 3000);
        }
      }
    });
  }, { threshold: 0, rootMargin: '1000px 0px' }); // Generous margin for items
});

onUnmounted(() => {
  // Revoke all Object URLs to prevent memory leaks
  thumbnails.value.forEach(url => URL.revokeObjectURL(url));
});

const registerObserver = ({ el, id }: { el: HTMLElement | null, id: string }) => {
  if (el && itemObserver && !observedElements.has(el)) {
    el.dataset.id = id;
    itemObserver.observe(el);
    observedElements.add(el);
  }
};

// Cleanup on data removal
watch(objects, (newObjs, oldObjs) => {
  const newIds = new Set<BinaryObjectId>(newObjs.map(object => object.id));
  if (oldObjs) {
    for (const oldObj of oldObjs) {
      if (!newIds.has(oldObj.id)) {
        const url = thumbnails.value.get(oldObj.id);
        if (url) URL.revokeObjectURL(url);
        thumbnails.value.delete(oldObj.id);
        thumbnailCount.value--;
      }
    }
  }
});

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
      thumbnailCount,
      displayLimit,
      thumbnails,
    },
  }) || {}),
});

